import json, urllib.request, urllib.parse, concurrent.futures, sys, time

BASE = "http://127.0.0.1:1933"
MODE = sys.argv[1] if len(sys.argv)>1 else "audit"

def get(path, params=None):
    url = BASE + path
    if params:
        url += "?" + urllib.parse.urlencode(params)
    with urllib.request.urlopen(url, timeout=60) as r:
        return json.load(r)

def post(path, body):
    req = urllib.request.Request(BASE+path, data=json.dumps(body).encode(),
                                 headers={"Content-Type":"application/json"}, method="POST")
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.load(r)

# 1. enumerate ALL session dirs via paginated fs/tree
sessions = []
offset = 0
while True:
    r = get("/api/v1/fs/tree", {"uri":"viking://user/default/sessions",
             "directories_only":"true","level_limit":"1","node_limit":"1000",
             "offset":offset,"output":"original"})
    rows = r["result"]
    sessions += [x["name"] for x in rows if x.get("isDir")]
    if not r.get("has_more") or not rows: break
    offset += len(rows)
print("ALL_SESSIONS", len(sessions))

# 2. per-session status
def stat(sid):
    try:
        d = get("/api/v1/sessions/"+urllib.parse.quote(sid))["result"]
        return sid, d
    except Exception as e:
        return sid, {"error":str(e)}

info = {}
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
    for sid,d in ex.map(stat, sessions):
        info[sid]=d

errs=[s for s,d in info.items() if "error" in d]
zero=[s for s,d in info.items() if "error" not in d and (d.get("memories_extracted") or {}).get("total",0)==0]
print("STATUS_ERR",len(errs),"ZERO_MEM",len(zero))

def archives_of(sid):
    out=[]
    off=0
    while True:
        try:
            r=get("/api/v1/fs/tree",{"uri":f"viking://user/default/sessions/{sid}/history",
                 "directories_only":"true","level_limit":"1","node_limit":"1000",
                 "offset":off,"output":"original"})
        except Exception:
            return out
        rows=r["result"]
        out += [x["name"] for x in rows if x.get("isDir")]
        if not r.get("has_more") or not rows: break
        off+=len(rows)
    return out

# 3. for zero-mem sessions with commits, inspect archives
def arc_detail(sid,aid):
    try:
        return sid,aid,get("/api/v1/sessions/"+urllib.parse.quote(sid)+"/archives/"+aid)["result"]
    except Exception as e:
        return sid,aid,{"error":str(e)}

targets=[]  # (sid, aid, sha)
arc_stat={}
zero_with_commit=[s for s in zero if (info[s].get("commit_count") or 0)>0]
print("ZERO_MEM_WITH_COMMIT",len(zero_with_commit))
jobs=[(s,a) for s in zero_with_commit for a in archives_of(s)]
with concurrent.futures.ThreadPoolExecutor(max_workers=16) as ex:
    for sid,aid,d in ex.map(lambda x:arc_detail(*x), jobs):
        st=d.get("status","ERR") if isinstance(d,dict) else "ERR"
        arc_stat[st]=arc_stat.get(st,0)+1
        if st=="failed" and d.get("messages_sha256"):
